package com.bank.audit;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

public class AuditPlacementSolver {

    private static final Logger log = Logger.getLogger(AuditPlacementSolver.class.getName());
    private final Set<Integer> cols = new HashSet<>();
    private final Set<Integer> diag1 = new HashSet<>(); // row - col
    private final Set<Integer> diag2 = new HashSet<>(); // row + col

    public List<List<Integer>> solve(int n) {
        List<List<Integer>> solutions = new ArrayList<>();
        backtrack(0, n, new ArrayList<>(), solutions);
        log.info(() -> "Found " + solutions.size() + " valid placements for n=" + n);
        return solutions;
    }

    // placement.get(r) = column of the queen in row r
    private void backtrack(int row, int n, List<Integer> placement, List<List<Integer>> solutions) {
        if (row == n) { solutions.add(new ArrayList<>(placement)); return; }
        for (int c = 0; c < n; c++) {
            if (cols.contains(c) || diag1.contains(row - c) || diag2.contains(row + c)) continue;
            cols.add(c); diag1.add(row - c); diag2.add(row + c); placement.add(c);
            backtrack(row + 1, n, placement, solutions);
            cols.remove(c); diag1.remove(row - c); diag2.remove(row + c);
            placement.remove(placement.size() - 1);           // backtrack
        }
    }
}
