package com.bank.audit;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class NQueensDemo {

    private static final Logger log = Logger.getLogger(NQueensDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Audit Checkpoint Placement (N-Queens)");
        AuditPlacementSolver solver = new AuditPlacementSolver();
        // placement list = column per row
        solver.solve(4).forEach(p -> log.info("Placement (col per row): " + p));
    }
}
